import{u as s,o,c as i,j as t,k as n,F as l,a8 as u,e as d,p as c}from"./chunks/framework.fPNBP_58.js";const p=["markdown-url"],h={"data-allow-mismatch":"",style:{display:"none"}},b=JSON.parse('{"title":"Climate Change Explorer for Tourism","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"ccet-overview","file":"https://gtif-austria.github.io/public-narratives/ccet-overview.md","title":"Climate Change Explorer for Tourism"},"relativePath":"narratives/ccet-overview.md","filePath":"narratives/[narrative].md"}'),g={name:"narratives/ccet-overview.md"},w=Object.assign(g,{setup(m){const e=c(!0);e.value=!1;const{params:r}=s();return(q,a)=>(o(),i("div",null,[t("client-only",null,[t("eox-storytelling",{"show-nav":"","markdown-url":n(r).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,p)]),t("div",h,[e.value?(o(),i(l,{key:0},[a[0]||(a[0]=u(' --- cover-image: https://raw.githubusercontent.com/GTIF-Austria/public-narratives/82e054c189bcc2619ff308c5268297f4c4474e0d/assets/MichaelaLandauer/CCET-Overview-1790868019973.png domain: Climate Change &amp; Tourism provider: GeoVille,Austria Tourism --- <h1 id="climate-change-explorer-for-tourism" tabindex="-1">Climate Change Explorer for Tourism <a class="header-anchor" href="#climate-change-explorer-for-tourism" aria-label="Permalink to &quot;Climate Change Explorer for Tourism &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/GTIF-Austria/public-narratives/82e054c189bcc2619ff308c5268297f4c4474e0d/assets/MichaelaLandauer/CCET-Overview-1790868019973.png&quot; }--&gt;&quot;">​</a></h1><h3 id="how-climate-related-geodata-can-support-sustainable-tourism-planning-and-development" tabindex="-1">How climate-related geodata can support sustainable tourism planning and development <a class="header-anchor" href="#how-climate-related-geodata-can-support-sustainable-tourism-planning-and-development" aria-label="Permalink to &quot;How climate-related geodata can support sustainable tourism planning and development&quot;">​</a></h3><h2 id="background-a-digital-climate-twin-for-tourism" tabindex="-1">Background: a digital climate twin for tourism <a class="header-anchor" href="#background-a-digital-climate-twin-for-tourism" aria-label="Permalink to &quot;Background: a digital climate twin for tourism&quot;">​</a></h2><p>Climate change poses growing challenges for tourism worldwide, significantly altering travel behaviour and the landscape of tourism offerings. The Alpine region is particularly affected by these developments, evident for example in the rapid retreat of glaciers, thawing permafrost, and a marked decline in snow depths. The <a href="https://aar2.ccca.ac.at/en" target="_blank" rel="noreferrer"><strong>second Austrian Climate Change Assessment Report</strong></a>, published in June 2025, shows that the country has already warmed by 3.1°C – with dramatic consequences for the population and the economy. Fostering sustainable development in tourism therefore requires well-founded knowledge of local climate hazards.</p><p>Planning and evaluating scenarios and climate-smart options for action require specific climate data and indicators to be combined with tourism-specific data. The Climate Change Explorer for Tourism (CCET) is designed to provide decision-makers in Austria&#39;s tourism regions with a user-friendly picture of the expected impacts of climate change, and an assessment of climate-related risk factors, based on climatic data alongside satellite-derived geoinformation.</p><p>The idea for the tool emerged from a workshop held as part of the Green Data Hub, together with Österreich Werbung, the World Bank and the Austrian Federal Computing Centre (BRZ) – conceived as a digital “climate twin” for tourism, providing historical, current and forecast data to build awareness and support informed decisions. Building on this, a prototype was developed in consultation with tourism organisations and mountain railway operators, and has since been advanced further by <a href="https://www.geoville.com/" target="_blank" rel="noreferrer">GeoVille</a>, <a href="https://b2b.austria.info/de-at/" target="_blank" rel="noreferrer">Österreich Werbung</a>, <a href="https://eox.at/" target="_blank" rel="noreferrer">EOX</a> and <a href="https://www.brz.gv.at/" target="_blank" rel="noreferrer">BRZ</a> as part of Digital Twin Austria (GTIF-AT EA).</p><p>Stakeholder workshops distilled a wide range of user stories into three use cases, each shedding light on a different facet of the project&#39;s guiding question:</p><p><strong>“How can we factor climate change into tourism planning and development in Austria?”</strong></p><h2 id="climate-indicators" tabindex="-1">Climate indicators <a class="header-anchor" href="#climate-indicators" aria-label="Permalink to &quot;Climate indicators &lt;!--{ as=&quot;eox-map&quot; mode=&quot;tour&quot; position=&quot;right&quot; }--&gt;&quot;">​</a></h2><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&lt;!--{ layers=&#39;[{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;cloudless-2025;:;EPSG:3857&quot;,&quot;title&quot;:&quot;EOxCloudless 2025&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/s2cloudless-2025_3857/default/g/{z}/{y}/{x}.jpeg&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ EOxCloudless 2025: &lt;a href=\\&quot;//s2maps.eu\\&quot; target=\\&quot;_blank\\&quot;&gt;Sentinel-2 cloudless - s2maps.eu&lt;/a&gt; by &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX IT Services GmbH&lt;/a&gt; (Contains modified Copernicus Sentinel data 2025) }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}},{&quot;type&quot;:&quot;VectorTile&quot;,&quot;declutter&quot;:true,&quot;properties&quot;:{&quot;id&quot;:&quot;climate_indicators;:;2026-05-26T00:00:00Z;:;Climate Indicators;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Climate Indicators&quot;},&quot;source&quot;:{&quot;type&quot;:&quot;VectorTile&quot;,&quot;format&quot;:{&quot;type&quot;:&quot;MVT&quot;},&quot;url&quot;:&quot;https://eoapi.workspace.gtif-eox.hub-otc.eox.at/vector/collections/public.climate_flat_geoms_master/tiles/WebMercatorQuad/{z}/{x}/{y}?scenario=rcp45&amp;metric=hot_days&amp;decade=2051_2060&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;},&quot;style&quot;:{&quot;variables&quot;:{&quot;scenario&quot;:&quot;rcp45&quot;,&quot;decade&quot;:&quot;2051_2060&quot;,&quot;month&quot;:&quot;jul&quot;,&quot;selected_elevation&quot;:&quot;full&quot;,&quot;selected_metric&quot;:&quot;hot_days&quot;,&quot;aggregation&quot;:&quot;mean&quot;,&quot;combined_prop&quot;:&quot;full_jul_mean&quot;,&quot;vmin&quot;:0,&quot;vmax&quot;:10},&quot;tooltip&quot;:[{&quot;id&quot;:&quot;tourism_region&quot;,&quot;title&quot;:&quot;Region&quot;},{&quot;id&quot;:&quot;scenario&quot;,&quot;title&quot;:&quot;Scenario&quot;},{&quot;id&quot;:&quot;metric&quot;,&quot;title&quot;:&quot;Metric&quot;},{&quot;id&quot;:&quot;full_jul_mean&quot;,&quot;title&quot;:&quot;Value (full | 2051_2060 jul)&quot;,&quot;decimals&quot;:2}],&quot;fill-color&quot;:[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;coalesce&quot;,[&quot;get&quot;,&quot;full_jul_mean&quot;],0],0],[&quot;-&quot;,10,0]],0,[254,224,210,1],0.143,[252,187,161,1],0.286,[252,146,114,1],0.429,[251,106,74,1],0.571,[239,59,44,1],0.714,[203,24,29,1],0.857,[165,15,21,1],1,[103,0,13,1]],&quot;stroke-color&quot;:&quot;black&quot;,&quot;stroke-width&quot;:1}},{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;overlay_bright;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Overlay labels&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/overlay_base_bright_3857/default/g/{z}/{y}/{x}.png&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ Overlay: Data &amp;copy; &lt;a href=\\&quot;http://www.openstreetmap.org/copyright\\&quot; target=\\&quot;_blank\\&quot;&gt;OpenStreetMap&lt;/a&gt; contributors, Made with Natural Earth, Rendering &amp;copy; &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX&lt;/a&gt; }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}}]&#39; zoom=&quot;7.227223813483254&quot; center=[13.135756031161442,48.05016548602643] projection=&quot;&quot; animationOptions={duration:500}}--&gt;&quot;">​</a></h3><h4 id="hot-days-in-austria-2051-2060" tabindex="-1">Hot days in Austria 2051-2060 <a class="header-anchor" href="#hot-days-in-austria-2051-2060" aria-label="Permalink to &quot;Hot days in Austria 2051-2060&quot;">​</a></h4><p>The map shows the projected number of hot days (&gt; 30° Celsius) in July in Austria between 2051 and 2060, based on a moderate climate scenario (RCP 4.5). The darker the colour, the hotter the region. Gaps in the map indicate that some municipalities cannot be assigned to a tourist destination.</p><h2 id="the-bigger-picture" tabindex="-1">The bigger picture <a class="header-anchor" href="#the-bigger-picture" aria-label="Permalink to &quot;The bigger picture&quot;">​</a></h2><p>Beyond the three use cases, the project&#39;s operational concept frames a set of longer-term goals for the tool – addressing the challenges of climate change through informed decisions, better planning and greater awareness:</p><ul><li><p><strong>Tourism management</strong>: supporting sustainable planning and adapting tourism offerings and infrastructure, balancing economic and ecological goals.</p></li><li><p><strong>Public awareness</strong>: making climate impacts understandable to a wider audience, to build awareness and encourage engagement with climate action.</p></li><li><p><strong>Informed decision-making</strong>: giving policymakers, scientists and businesses a common, evidence-based picture to work from.</p></li><li><p><strong>Risk management</strong>: as real-time and forecast data are integrated, supporting earlier warnings and better-prepared responses to extreme weather and natural hazards.</p></li><li><p><strong>Research and development</strong>: providing data access and analysis tools that researchers can use to study patterns, test hypotheses and generate new insights.</p></li><li><p><strong>Economic opportunity</strong>: giving businesses and investors a basis for sustainable planning and investment decisions.</p></li><li><p><strong>Transparency and collaboration</strong>: encouraging open data-sharing and joint problem-solving across government, science and industry.</p></li></ul><h2 id="the-three-use-cases" tabindex="-1">The three Use Cases <a class="header-anchor" href="#the-three-use-cases" aria-label="Permalink to &quot;The three Use Cases&quot;">​</a></h2><p>Explore each Use Case in detail on its own page:</p><ul><li><p><a href="https://gtif-austria.info/explore?indicator=climate_indicators&amp;x=13.3000&amp;y=47.7675&amp;z=8.2272&amp;template=light&amp;datetime=2026-05-26" target="_blank" rel="noreferrer"><strong>Use Case 1 – Climate Indicators</strong></a>**: how the climate in a given region is changing, using indicators such as hot days, tropical nights and heavy precipitation days.</p></li><li><p><a href="https://gtif-austria.info/explore?indicator=tourism_uc2_stats&amp;x=13.3000&amp;y=47.7675&amp;z=8.2272&amp;template=light&amp;datetime=2030-01-01" target="_blank" rel="noreferrer"><strong>Use Case 2 – Climate Hazards</strong></a>: how exposed tourism destinations are to climate-related hazards, from declining snow cover to flooding and heat stress.</p></li><li><p><a href="https://gtif-austria.info/explore?indicator=tourism_uc3_correlation&amp;x=13.7500&amp;y=47.2688&amp;z=7.2410&amp;template=light&amp;datetime=2026-02-15" target="_blank" rel="noreferrer"><strong>Use Case 3 – Tourism Indicators</strong></a>: how climate change is already reflected in visitor demand, by linking climate data with overnight-stay forecasts.</p></li></ul><p>Each use case draws on different datasets and time horizons, chosen to suit its particular question:</p><p><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/d89d4f2e2a4350c6c9bf5a499f1ce744dc5534e8/assets/MichaelaLandauer/Bild-8-1790260140287.png" alt="Bild (8).png"></p><p><em>Note: Use Case 1 relies on the ÖKS15 climate projections under two future scenarios (RCP4.5/RCP8.5) running to 2100, whereas Use Cases 2 and 3 are built on observed historical data (SNOWGRID-CL, SPARTACUS) combined with recent and forecast tourism data, focused on the present and very near future.</em></p><h2 id="what-you-can-do-with-the-tool" tabindex="-1">What you can do with the tool <a class="header-anchor" href="#what-you-can-do-with-the-tool" aria-label="Permalink to &quot;What you can do with the tool&quot;">​</a></h2><p>Across all three use cases, the Climate Change Explorer for Tourism offers the same set of interactive functions:</p><ul><li><p><strong>Compare</strong>: place regions and destinations side by side, freely selected.</p></li><li><p><strong>Simulate</strong>: play through future climate changes and the effect of possible measures.</p></li><li><p><strong>Explore time</strong>: a time slider spanning months and decades, making the summer/winter contrast visible.</p></li><li><p><strong>Locate</strong>: search for a location and hover over the map for exact values.</p></li><li><p><strong>Interpret</strong>: guidance to help make sense of each indicator.</p></li><li><p><strong>Dowload</strong>: use data for your own analysis and applications.</p></li></ul><p><em>Note: the tool does not yet operate in real time at this stage of the project.</em></p><p><img src="https://raw.githubusercontent.com/GTIF-Austria/public-narratives/cd847cffcb90173936b99ae4ff9487eea77f8293/assets/MichaelaLandauer/Bild-5-1793788455887.png" alt="Bild (5).png"><strong>Compare mode</strong>: The dataset also allows for a comparison between two destinations: in this case, Innsbruck and its holiday villages (in blue), and the Mostviertel region (in orange).</p><h2 id="who-it-s-for" tabindex="-1">Who it&#39;s for <a class="header-anchor" href="#who-it-s-for" aria-label="Permalink to &quot;Who it&#39;s for&quot;">​</a></h2><p>Beyond tourism regions, destinations, businesses and municipalities, the project&#39;s operational concept names a wider circle of users who benefit from the tool:</p><ul><li><p><strong>Cable car and ski resort operators</strong>: assessing snow reliability, planning snowmaking and investment.</p></li><li><p><strong>Tourism associations and destinations</strong>: developing year-round tourism, timing marketing to the climate calendar.</p></li><li><p><strong>Hospitality and gastronomy</strong>: optimising seasonal planning, preparing heat protection for guests and staff.</p></li><li><p><strong>Regional and national policymakers</strong>: shaping funding programmes, tourism strategy and spatial planning with evidence.</p></li><li><p><strong>Science and research</strong>: validating indicators and helping develop the platform&#39;s methodology.</p></li></ul><h2 id="how-the-tool-works" tabindex="-1">How the tool works <a class="header-anchor" href="#how-the-tool-works" aria-label="Permalink to &quot;How the tool works&quot;">​</a></h2><p>Behind the three use cases lies a five-stage operating model that turns raw data into decision support:</p><p><strong>1. Data delivery</strong>: climate data (GeoSphere Austria), tourism statistics (Statistik Austria), natural-hazard data, geodata and satellite data (Copernicus) arrive from a wide range of sources.</p><p><strong>2. Data integration</strong>: datasets are cross-referenced spatially (e.g. matching 1 km climate grids to municipalities), temporally (aligning daily, monthly and seasonal values with booking periods), and by elevation band.</p><p><strong>3. Processing and quality assurance</strong>: data is cleaned, standard indicators are derived, and results are aggregated to the relevant decision-making levels (day, month, season; municipality, region, state).</p><p><strong>4. Analysis and visualisation</strong>: results are shown as choropleth maps and charts within the GTIF framework, with filters and a comparison mode for different regions, parameters or time periods.</p><p><strong>5. Decision support and monitoring</strong>: thresholds and alerts, scenario calculators and structured reports translate the data into concrete options for tourism regions, policymakers and funding bodies.</p><h2 id="ccet-and-austria-s-vision-t" tabindex="-1">CCET and Austria&#39;s Vision T <a class="header-anchor" href="#ccet-and-austria-s-vision-t" aria-label="Permalink to &quot;CCET and Austria&#39;s Vision T&quot;">​</a></h2><p>In June 2026, the Federal Ministry for Economic Affairs, Energy and Tourism presented <a href="https://www.bmwet.gv.at/Themen/Tourismus/vision-t.html" target="_blank" rel="noreferrer">Vision T</a>, Austria&#39;s national tourism strategy to 2035, structured around five strategic fields of action. The project&#39;s own operational concept explicitly names Vision T as a reference use case for the tool, and four of the five fields connect directly to what the CCET delivers:</p><ul><li><p><strong>Resources &amp; Responsibility</strong>: the strongest fit. This field&#39;s 2035 target picture explicitly names temperature changes and weather fluctuations as a new challenge and calls for recognising climate adaptation needs early – precisely what the three CCET use cases are designed to deliver.</p></li><li><p><strong>Economic Strength &amp; Resilience</strong>: a secondary fit. The strategy&#39;s tension field “year-round operation vs. economic viability” explicitly notes that climate-driven demand shifts must be factored into season extension, which Use Cases 1 and 3 speak to directly.</p></li><li><p><strong>Innovation &amp; Digitalisation</strong>: a structural fit. The strategy calls for “networked data spaces” with low-threshold access to high-quality tourism data – exactly the role the CCET plays for climate-related information.</p></li><li><p><strong>Value &amp; Co-Design</strong>: a fourth fit. This field is about positioning tourism as a driver for liveable regions, developed together with local communities. By showing concretely how living conditions in a municipality are changing – for example rising heat exposure – the CCET gives residents and tourism actors a shared, evidence-based starting point for jointly developing better infrastructure and quality of life.</p></li></ul><p>Overall, four of Vision T&#39;s five strategic fields connect to the CCET – only Labour Market &amp; Skilled Workers remains unaffected – underlining the tool&#39;s broad relevance for the strategy.</p><h2 id="outlook" tabindex="-1">Outlook <a class="header-anchor" href="#outlook" aria-label="Permalink to &quot;Outlook&quot;">​</a></h2><p>The project&#39;s operational concept also outlines ideas under discussion for further development: daily data feeds from the Green Data Hub and the Österreich Werbung Tourism Data Space, an AI assistant to help translate data into concrete actions, role-based access for different user groups, and usage-based recommendations. These are exploratory directions, not features of the current tool.</p><h2 id="in-summary" tabindex="-1">In summary <a class="header-anchor" href="#in-summary" aria-label="Permalink to &quot;In summary&quot;">​</a></h2><p>Together, the three use cases make climate change tangible for Austria&#39;s tourism sector in three complementary steps: Use Case 1 shows how the climate itself is changing; Use Case 2 shows what hazards this creates for destinations, starting with the decline in snow cover; and Use Case 3 shows how these changes are already reflected in visitor demand. Taken together, the Climate Change Explorer for Tourism gives tourism regions, destinations, businesses and public administration an evidence-based foundation for climate-smart planning.</p>',45))],64)):d("",!0)])]))}});export{b as __pageData,w as default};
